  assert.equal(cipher.binding.revision,RATIO_UUID_4000);assert.match(cipher.binding.revision,/^[a-f0-9]{8}-[a-f0-9]{4}-4[a-f0-9]{3}-[89ab][a-f0-9]{3}-[a-f0-9]{12}$/);
