function refinementUiAdapter(page,forward=true){
  assert.equal(typeof forward,'boolean');
  assert.equal(ratioUiHash(page),forward?ratioPresentationUiSha256:ratioRefinementUiSha256,'unreviewed refinement input');
  let result=page;
  for(const r of ratioRefinementRegions){const [from,to]=forward?[r.prior,r.next]:[r.next,r.prior];assert.equal(result.split(from).length,2);result=result.replace(from,()=>to);}
  assert.equal(ratioUiHash(result),forward?ratioRefinementUiSha256:ratioPresentationUiSha256,'unreviewed refinement output');return result;
}
