test('ciphertext reuse refuses changed metadata, expiry, auth drift, corruption and network errors',async t=>{
 const f=await fixture(t);
 for(const mode of ['expired','size','pin','owner','network','corrupt','role']){
  const c=harness(f,{truncated:true,candidate:false});await c.view();c.close(false);const get=c.ghApi;
  if(mode==='expired')c._ratioCipherCache.at-=600001;
  if(mode==='size')c._ratioCipherCache.size++;
  if(mode==='pin')c._ratioCipherCache.pin+='invalid';
  if(mode==='corrupt')c._ratioCipherCache.raw='{}';
  if(mode==='owner')c.ghApi=async(...args)=>{const g=await get(...args);return {...g,owner:{...g.owner,id:321}};};
  if(mode==='network')c.ghApi=async()=>{throw Error('SYNTHETIC_FAILURE');};
  if(mode==='role')c.state.authorized=false;
  await c.view();
  if(['expired','size','pin'].includes(mode)){assert.equal(c.fetches.length,2,mode);assert.equal(c.renderCalls,2,mode);}
  else {assert.equal(c.renderCalls,1,mode);assert.equal(c.element('ratioContent').innerHTML,'',mode);if(mode!=='role')assert.equal(c._ratioCipherCache,null,mode);}
 }
});
